ON CONFLICT (id) DO NOTHING;


ON CONFLICT (numero_processo) DO UPDATE SET
  cliente_id = EXCLUDED.cliente_id,
  materia = EXCLUDED.materia,
  data_ultimo_andamento = EXCLUDED.data_ultimo_andamento,
  prazo_processual = EXCLUDED.prazo_processual,
  fase_processual = EXCLUDED.fase_processual,
  tipo_pendencia = EXCLUDED.tipo_pendencia,
  status_tarefa = EXCLUDED.status_tarefa,
  vara_juizo_origem = EXCLUDED.vara_juizo_origem,
  observacoes = EXCLUDED.observacoes;
